// Decide today's touches: step 1 for approved (queued) prospects, step 2 at
// day 3, step 3 (breakup) at day 8, mark lost 3 days after the breakup.
const DAY = 86400000;
const now = Date.now();

const hist = {}; // prospect_id -> { firstAt, lastAt, maxStep }
for (const i of $('Get Outbound History').all()) {
  const c = i.json;
  if (!c || !c.prospect_id) continue;
  const t = new Date(c.sent_at).getTime();
  const h = hist[c.prospect_id] || { firstAt: t, lastAt: t, maxStep: 0 };
  h.firstAt = Math.min(h.firstAt, t);
  h.lastAt = Math.max(h.lastAt, t);
  h.maxStep = Math.max(h.maxStep, c.sequence_step || 1);
  hist[c.prospect_id] = h;
}

const out = [];

for (const i of $('Get Queued').all()) {
  const p = i.json;
  if (!p || !p.id) continue;
  // 45-day re-contact lockout
  if (p.last_contacted && now - new Date(p.last_contacted).getTime() < 45 * DAY) continue;
  out.push({ json: { action: 'send', step: 1, angle: 'opener', ...p } });
}

for (const i of $('Get In Sequence').all()) {
  const p = i.json;
  if (!p || !p.id) continue;
  const h = hist[p.id];
  if (!h) continue;
  if (h.maxStep >= 3) {
    if (now - h.lastAt >= 3 * DAY) out.push({ json: { action: 'mark_lost', ...p } });
  } else if (h.maxStep === 2) {
    if (now - h.firstAt >= 8 * DAY) out.push({ json: { action: 'send', step: 3, angle: 'breakup', ...p } });
  } else if (h.maxStep === 1) {
    if (now - h.firstAt >= 3 * DAY) out.push({ json: { action: 'send', step: 2, angle: 'follow_up', ...p } });
  }
}

return out;

// Build the OpenRouter request for this touch, FROM THE BRAND BRAIN.
//
// The voice used to live here, hardcoded: a system string plus a per-vertical
// example line, editable only by opening this node inside a workflow JSON. It
// now comes from brand_brain rows tagged channel='email', so the copy is
// versioned with the brand and changing it is a row edit, not a redeploy.
const p = $input.first().json;

// --- the brief -------------------------------------------------------------
const brain = $('Read the brand brain').all().map((i) => i.json)
  .filter((r) => r && r.kind && r.content);
if (!brain.length) {
  throw new Error('brand_brain returned no email rows - refusing to write off-brief. Check seed-brand-brain-outreach.sql ran.');
}

// sanaku_prospects.vertical is TEXT and says 'law_firm'. brand_brain.vertical
// is the enum public.vertical and says 'personal_injury_law'. Same audience,
// two spellings - the divergence flagged in migration 022. Without this map a
// law firm silently gets no ICP section and the email is written blind.
const BRAIN_VERTICAL = {
  law_firm: 'personal_injury_law',
  accounting_tax: 'accounting_tax',
  therapy: 'therapy',
  financial_advisory: 'financial_advisory',
  family_office: 'family_office',
};
const bv = BRAIN_VERTICAL[p.vertical] || null;

const section = (kinds, vertical) => brain
  .filter((r) => kinds.includes(r.kind))
  .filter((r) => vertical === undefined || !r.vertical || r.vertical === vertical)
  .map((r) => '### ' + r.title + '\n' + r.content)
  .join('\n\n');

const rules = section(['rule']);
const voice = section(['voice', 'brand_voice']);
const positioning = section(['offer']);
const icp = section(['icp'], bv);

if (!icp) {
  // Loud, not silent. An email written with no idea who it is going to is
  // worse than no email, and this is the failure the vertical map exists to
  // prevent - so it must not degrade quietly if a new vertical appears.
  throw new Error('no ICP row for vertical ' + p.vertical + ' (mapped to ' + bv + '). Add one to brand_brain before contacting this vertical.');
}

// --- what we actually observed about this firm -----------------------------
const sig = p.signals || {};
const evidence = [];
if (sig.detected && sig.detected.ads) evidence.push('they are running paid ads');
if (!sig.detected || !sig.detected.chat) evidence.push('no chat or intake widget on the site');
if (!sig.detected || !sig.detected.booking) evidence.push('no online booking');
if (sig.has_contact_form) evidence.push('intake goes to a plain contact form');
if (sig.review_count) evidence.push(sig.review_count + ' Google reviews at ' + sig.rating);

const ANGLES = {
  opener: 'TOUCH 1, the opener.',
  follow_up: 'TOUCH 2, day 3, no reply. A different angle - not a nudge.',
  breakup: 'TOUCH 3, day 8, the breakup. Two or three sentences.',
};

const first = (p.first_name || (p.contact_name || '').split(' ')[0] || '').trim();

const system = [
  'You write cold outreach email for Ismail Rogers-Wright, who builds AI systems that run inside a firm\'s own building.',
  'You are writing ONE email. Return it exactly as specified at the end - nothing else.',
  '',
  '## Positioning', positioning,
  '', '## How this brand talks', voice,
  '', '## Rules - these bind you absolutely', rules,
  '', '## Who you are writing to', icp,
].join('\n');

const user = [
  'Firm: ' + p.company_name,
  'Reader: ' + (p.contact_name || 'unknown') + (p.contact_title ? ' (' + p.contact_title + ')' : ''),
  first ? 'Greet them as: ' + first : 'No first name known - do not invent one, open without a salutation.',
  'Vertical: ' + p.vertical,
  evidence.length ? 'What we observed on their site: ' + evidence.join('; ') : '',
  '',
  ANGLES[p.angle] || ANGLES.opener,
  '',
  'Return EXACTLY this, no preamble and no commentary:',
  'SUBJECT: <the subject line on one line>',
  'BODY:',
  '<the email body, plain text, as many paragraphs as it needs>',
].filter(Boolean).join('\n');

// Same rotating free pool the content studio uses, for the same reason: the
// free tier throttles constantly and a single model is not schedulable.
const __env = (k) => (typeof $env !== 'undefined' && $env[k]) ? $env[k] : null;
const __pinned = __env('OPENROUTER_MODEL');
const __pool = (__env('OPENROUTER_MODELS') || '').split(',').map((x) => x.trim()).filter(Boolean);
const __models = __pool.length ? __pool : ['google/gemma-4-26b-a4b-it:free', 'google/gemma-4-31b-it:free'];
const __ordered = __pinned ? [__pinned].concat(__models.filter((m) => m !== __pinned)) : __models;
const __trio = __ordered.filter((m, i) => __ordered.indexOf(m) === i).slice(0, 3);

return [{ json: { ...p, orBody: {
  model: __trio[0],
  models: __trio,
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  max_tokens: 600,
  temperature: 0.75,
} } }];

// Parse the model's reply into a subject and a body, and hold it for review.
//
// SUBJECT:/BODY: rather than JSON, for the reason the content studio learned
// the hard way: a free-tier model writing multi-paragraph prose inside a JSON
// string gets the newline escaping wrong and the whole draft is lost. Two
// labelled lines need no escaping at all.
const p = $('Build Prompt').first().json;
const res = $input.first().json;

const raw = res && res.choices && res.choices[0] && res.choices[0].message
  ? res.choices[0].message.content : null;
if (!raw) {
  const e = res && res.error;
  throw new Error(e ? ('model error: ' + String(e.message || JSON.stringify(e)).slice(0, 160))
                    : 'model returned no content');
}

// Reasoning models put their working first; ignore anything before SUBJECT:.
let text = String(raw).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();

const sm = text.match(/^\s*SUBJECT:\s*(.+)$/mi);
if (!sm) throw new Error('draft has no SUBJECT: line - got: ' + text.slice(0, 200));

// BODY: is optional. Models reliably label the subject and then just start
// writing, which is the natural thing to do and not worth rejecting a good
// draft over - so everything after the subject line is the body unless a
// BODY: label says otherwise. The subject is the only part that genuinely
// needs a delimiter, because it has to be lifted out of the prose.
const bm = text.match(/^\s*BODY:\s*\n?([\s\S]+)$/mi);
let subject = sm[1].trim().replace(/^["'“]|["'”]$/g, '').trim();
let body = (bm ? bm[1] : text.slice(sm.index + sm[0].length)).trim();
if (!body) throw new Error('draft has a subject but no body');

// Guardrails the brief states but a model still breaks. Caught here rather
// than in review, because a human skimming forty drafts will miss them.
const problems = [];
if (!subject) problems.push('empty subject');
if (subject.length > 90) problems.push('subject over 90 chars');
if (/\bre:\s/i.test(subject)) problems.push('fake "Re:" in subject');
if (/(free|guarantee|act now|limited time|urgent|unlock|boost|10x|ROI)/i.test(subject)) {
  problems.push('spam-trigger word in subject');
}
if (/hope (this|you)\s|just following up|quick question/i.test(body)) {
  problems.push('banned opener phrase in body');
}
const words = body.split(/\s+/).filter(Boolean).length;
if (words > 220) problems.push('body ' + words + ' words, over the 130-word brief');
const asks = (body.match(/\?/g) || []).length;
if (asks > 1) problems.push(asks + ' questions - the brief allows exactly one');

return [{ json: {
  id: p.id,
  company_name: p.company_name,
  contact_email: p.contact_email,
  contact_name: p.contact_name,
  vertical: p.vertical,
  step: p.step,
  angle: p.angle,
  draft_subject: subject,
  draft_body: body,
  draft_model: (res.model || null),
  draft_words: words,
  draft_problems: problems,
} }];

// Summarize what this run did (reads the plan, not the loop debris).
const planned = $('Plan Touches').all().map((i) => i.json);
const sends = planned.filter((p) => p.action === 'send');
const lost = planned.filter((p) => p.action === 'mark_lost');
const byStep = { 1: 0, 2: 0, 3: 0 };
for (const s of sends) byStep[s.step]++;
const html = '<p>Sanaku outreach run complete.</p><ul>' +
  '<li>Openers sent: ' + byStep[1] + '</li>' +
  '<li>Day-3 follow-ups: ' + byStep[2] + '</li>' +
  '<li>Day-8 breakups: ' + byStep[3] + '</li>' +
  '<li>Marked lost: ' + lost.length + '</li></ul>' +
  (sends.length ? '<p>' + sends.map((s) => s.company_name + ' (step ' + s.step + ')').join('<br>') + '</p>' : '');
return [{ json: { html, subject: 'Sanaku outreach: ' + sends.length + ' sent, ' + lost.length + ' closed' } }];

// The first gate closes here. The draft is written onto the prospect and the
// workflow stops - no send node exists on this path at all, which is a stronger
// guarantee than a disabled one.
const d = $input.first().json;
const body = {
  draft_subject: d.draft_subject,
  draft_body: d.draft_body,
  draft_step: d.step,
  draft_angle: d.angle,
  draft_model: d.draft_model,
  draft_generated_at: new Date().toISOString(),
  draft_edited: false,
  status: 'draft_review',
};
// Anything the guardrails flagged rides along in notes so it is visible in the
// dashboard next to the text, rather than only in an execution log nobody opens.
if (d.draft_problems && d.draft_problems.length) {
  body.notes = 'DRAFT WARNINGS: ' + d.draft_problems.join('; ');
}
return [{ json: { id: d.id, body } }];
